fn c_string_visible(s: Expression) -> Expression {
    let nul = expr(ExprKind::Lit(Literal::Str("\0".to_string())));
    let nul_idx = call_expr(ident("__c_str_index_of"), vec![s.clone(), nul]);
    let string_view = expr(ExprKind::Ternary {
        cond: Box::new(expr(ExprKind::Binary {
            op: BinOp::GtEq,
            left: Box::new(nul_idx.clone()),
            right: Box::new(int_lit(0)),
        })),
        then: Box::new(call_expr(
            member(s.clone(), "substring"),
            vec![int_lit(0), nul_idx],
        )),
        else_: Box::new(s.clone()),
    });
    expr(ExprKind::Ternary {
        cond: Box::new(pointers::is_carray_ptr_kind(s.clone())),
        then: Box::new(carray_pointer_to_c_string(s)),
        else_: Box::new(string_view),
    })
}

fn c_char_pointer_visible_value(value: Expression) -> Expression {
    let tmp = "__c_charptr_string_value";
    let tmp_value = ident(tmp);
    let body = ternary_expr(
        binary_expr(
            BinOp::Eq,
            expr(ExprKind::Unary {
                op: UnaryOp::Typeof,
                expr: Box::new(tmp_value.clone()),
            }),
            str_lit("number"),
        ),
        call_expr(ident("__libc_char_to_str"), vec![tmp_value.clone()]),
        ternary_expr(
            pointers::is_carray_ptr_kind(tmp_value.clone()),
            {
                let carray_element = expr(ExprKind::Index {
                    object: Box::new(member(tmp_value.clone(), CARRAY_BASE_KEY)),
                    index: Box::new(member(tmp_value.clone(), CARRAY_IDX_KEY)),
                    null_safe: false,
                });
                let carray_element_name = member(carray_element.clone(), "name");
                ternary_expr(
                    binary_expr(
                        BinOp::NotEq,
                        expr(ExprKind::Unary {
                            op: UnaryOp::Typeof,
                            expr: Box::new(carray_element_name.clone()),
                        }),
                        str_lit("undefined"),
                    ),
                    c_string_visible(carray_element_name),
                    c_string_visible(carray_pointer_to_c_string(tmp_value.clone())),
                )
            },
            ternary_expr(
                binary_expr(
                    BinOp::Eq,
                    expr(ExprKind::Unary {
                        op: UnaryOp::Typeof,
                        expr: Box::new(tmp_value.clone()),
                    }),
                    str_lit("object"),
                ),
                ternary_expr(
                    binary_expr(
                        BinOp::NotEq,
                        expr(ExprKind::Unary {
                            op: UnaryOp::Typeof,
                            expr: Box::new(member(tmp_value.clone(), "name")),
                        }),
                        str_lit("undefined"),
                    ),
                    c_string_visible(member(tmp_value.clone(), "name")),
                    str_lit(""),
                ),
                c_string_visible(tmp_value),
            ),
        ),
    );
    call_expr(
        expr(ExprKind::Lambda {
            params: vec![Param {
                name: tmp.to_string(),
                type_hint: None,
                default: None,
                pass_by: PassBy::Value,
                is_rest: false,
                is_kwargs: false,
                is_optional: false,
                is_nullable: false,
            }],
            body: LambdaBody::Expr(Box::new(body)),
            is_async: false,
            captures: vec![],
        }),
        vec![value],
    )
}

fn c_array_string_visible(s: Expression) -> Expression {
    call_expr(ident("__libc_char_to_str"), vec![s])
}

fn strip_runtime_pointer_cast(value: Expression) -> Expression {
    match value.kind {
        ExprKind::Cast { expr: inner, .. } => strip_runtime_pointer_cast(*inner),
        ExprKind::Ternary { cond, then, else_ } => expr(ExprKind::Ternary {
            cond: Box::new(strip_runtime_pointer_cast(*cond)),
            then: Box::new(strip_runtime_pointer_cast(*then)),
            else_: Box::new(strip_runtime_pointer_cast(*else_)),
        }),
        ExprKind::Binary { op, left, right } => expr(ExprKind::Binary {
            op,
            left: Box::new(strip_runtime_pointer_cast(*left)),
            right: Box::new(strip_runtime_pointer_cast(*right)),
        }),
        ExprKind::Unary { op, expr: inner } => expr(ExprKind::Unary {
            op,
            expr: Box::new(strip_runtime_pointer_cast(*inner)),
        }),
        ExprKind::Member {
            object,
            field,
            null_safe,
        } => expr(ExprKind::Member {
            object: Box::new(strip_runtime_pointer_cast(*object)),
            field,
            null_safe,
        }),
        ExprKind::Index {
            object,
            index,
            null_safe,
        } => expr(ExprKind::Index {
            object: Box::new(strip_runtime_pointer_cast(*object)),
            index: Box::new(strip_runtime_pointer_cast(*index)),
            null_safe,
        }),
        ExprKind::Call {
            callee,
            args,
            optional,
        } => expr(ExprKind::Call {
            callee: Box::new(strip_runtime_pointer_cast(*callee)),
            args: args
                .into_iter()
                .map(|mut arg| {
                    arg.value = strip_runtime_pointer_cast(arg.value);
                    arg
                })
                .collect(),
            optional,
        }),
        ExprKind::Sequence(parts) => expr(ExprKind::Sequence(
            parts.into_iter().map(strip_runtime_pointer_cast).collect(),
        )),
        other => expr(other),
    }
}

fn carray_pointer_to_c_string(ptr: Expression) -> Expression {
    let base = member(ptr.clone(), CARRAY_BASE_KEY);
    expr(ExprKind::Ternary {
        cond: Box::new(expr(ExprKind::Binary {
            op: BinOp::Eq,
            left: Box::new(expr(ExprKind::TypeOf(Box::new(base.clone())))),
            right: Box::new(str_lit("string")),
        })),
        then: Box::new(call_expr(
            member(base, "substring"),
            vec![member(ptr.clone(), CARRAY_IDX_KEY)],
        )),
        else_: Box::new(pointers::carray_chars_to_string(ptr)),
    })
}

fn strspn_literal_len(s: &str, accept: &str) -> usize {
    // Case-sensitive, matching C strspn and the `__c_strspn_h` runtime helper.
    s.chars().take_while(|ch| accept.contains(*ch)).count()
}

fn strncmp_literal_value(a: &str, b: &str, n: usize) -> i64 {
    if n == 0 {
        return 0;
    }
    let left: String = a.chars().take(n).collect();
    let right: String = b.chars().take(n).collect();
    match left.cmp(&right) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

/// True if `e` is an Object literal tagged as a carray (from `make_carray_ptr`).
fn is_carray_object(e: &Expression) -> bool {
    if let ExprKind::Cast { expr, .. } = &e.kind {
        return is_carray_object(expr);
    }
    if matches!(&e.kind, ExprKind::Member { field, .. } if field == C_STRUCT_BACKING_POINTER_KEY) {
        return true;
    }
    if let ExprKind::Ternary { then, else_, .. } = &e.kind {
        let then_is_null = matches!(then.kind, ExprKind::Lit(Literal::Null));
        let else_is_null = matches!(else_.kind, ExprKind::Lit(Literal::Null));
        let then_is_carray = is_carray_object(then);
        let else_is_carray = is_carray_object(else_);
        return (then_is_carray || then_is_null)
            && (else_is_carray || else_is_null)
            && (then_is_carray || else_is_carray);
    }
    if let ExprKind::Object(ref props) = e.kind {
        props.iter().any(|p| {
            if let ObjectProperty::KeyValue { key, value } = p {
                if let (ExprKind::Lit(Literal::Str(k)), ExprKind::Lit(Literal::Str(v))) =
                    (&key.kind, &value.kind)
                {
                    return k == "__ref_kind" && v == CARRAY_KIND;
                }
            }
            false
        })
    } else {
        false
    }
}

fn is_cstruct_pointer_object(e: &Expression) -> bool {
    match &e.kind {
        ExprKind::Sequence(parts) => {
            return parts.last().is_some_and(is_cstruct_pointer_object);
        }
        ExprKind::Cast { expr, .. } => return is_cstruct_pointer_object(expr),
        _ => {}
    }
    if let ExprKind::Object(ref props) = e.kind {
        props.iter().any(|p| {
            if let ObjectProperty::KeyValue { key, value } = p {
                if let (ExprKind::Lit(Literal::Str(k)), ExprKind::Lit(Literal::Str(v))) =
                    (&key.kind, &value.kind)
                {
                    return k == REF_KIND_KEY && v == C_STRUCT_PTR_KIND;
                }
            }
            false
        })
    } else {
        false
    }
}

fn cstruct_pointer_byte_carray(e: &Expression) -> Option<Expression> {
    let ExprKind::Object(props) = &e.kind else {
        return None;
    };
    let mut is_cstruct = false;
    let mut base = None;
    for prop in props {
        let ObjectProperty::KeyValue { key, value } = prop else {
            continue;
        };
        if matches!(
            (&key.kind, &value.kind),
            (ExprKind::Lit(Literal::Str(k)), ExprKind::Lit(Literal::Str(v)))
                if k == REF_KIND_KEY && v == C_STRUCT_PTR_KIND
        ) {
            is_cstruct = true;
        } else if matches!(&key.kind, ExprKind::Lit(Literal::Str(k)) if k == CARRAY_BASE_KEY) {
            base = Some(value.clone());
        }
    }
    if !is_cstruct {
        return None;
    }
    Some(pointers::make_carray_ptr(
        expr(ExprKind::Array(vec![ArrayElement {
            value: base?,
            spread: false,
            key: None,
            by_ref: false,
        }])),
        int_lit(0),
    ))
}

fn carray_operand_expr(e: &Expression) -> Expression {
    if let ExprKind::Cast { expr, .. } = &e.kind {
        return carray_operand_expr(expr);
    }
    e.clone()
}

fn carray_base_ident(e: &Expression) -> Option<String> {
    let e = carray_operand_expr(e);
    if let ExprKind::Ternary { then, else_, .. } = &e.kind {
        return carray_base_ident(then).or_else(|| carray_base_ident(else_));
    }
    let ExprKind::Object(props) = e.kind else {
        return None;
    };
    for prop in props {
        let ObjectProperty::KeyValue { key, value } = prop else {
            continue;
        };
        if matches!(key.kind, ExprKind::Lit(Literal::Str(ref k)) if k == CARRAY_BASE_KEY) {
            if let ExprKind::Ident(name) = value.kind {
                return Some(name);
            }
        }
    }
    None
}

fn carray_zero_base_expr(e: &Expression) -> Option<Expression> {
    let e = carray_operand_expr(e);
    if let ExprKind::Ternary { cond, then, else_ } = &e.kind {
        let then_base = carray_zero_base_expr(then);
        let else_base = carray_zero_base_expr(else_);
        return match (then_base, else_base) {
            (Some(then_base), Some(else_base)) => Some(expr(ExprKind::Ternary {
                cond: cond.clone(),
                then: Box::new(then_base),
                else_: Box::new(else_base),
            })),
            (Some(base), None) if is_null_expr(else_) => Some(base),
            (None, Some(base)) if is_null_expr(then) => Some(base),
            _ => None,
        };
    }
    let ExprKind::Object(props) = e.kind else {
        return None;
    };
    let mut base = None;
    let mut idx_is_zero = false;
    for prop in props {
        let ObjectProperty::KeyValue { key, value } = prop else {
            continue;
        };
        if matches!(key.kind, ExprKind::Lit(Literal::Str(ref k)) if k == CARRAY_BASE_KEY) {
            base = Some(value);
        } else if matches!(key.kind, ExprKind::Lit(Literal::Str(ref k)) if k == CARRAY_IDX_KEY) {
            idx_is_zero = is_zero_expr(&value);
        }
    }
    if idx_is_zero { base } else { None }
}

fn carray_idx_value_expr(e: &Expression) -> Expression {
    let e = carray_operand_expr(e);
    if let ExprKind::Ternary { cond, then, else_ } = &e.kind {
        if is_carray_object(then) && is_carray_object(else_) {
            return expr(ExprKind::Ternary {
                cond: cond.clone(),
                then: Box::new(carray_idx_value_expr(then)),
                else_: Box::new(carray_idx_value_expr(else_)),
            });
        }
        if is_carray_object(then) && matches!(else_.kind, ExprKind::Lit(Literal::Null)) {
            return expr(ExprKind::Ternary {
                cond: cond.clone(),
                then: Box::new(carray_idx_value_expr(then)),
                else_: Box::new(int_lit(0)),
            });
        }
        if matches!(then.kind, ExprKind::Lit(Literal::Null)) && is_carray_object(else_) {
            return expr(ExprKind::Ternary {
                cond: cond.clone(),
                then: Box::new(int_lit(0)),
                else_: Box::new(carray_idx_value_expr(else_)),
            });
        }
    }
    member(e, CARRAY_IDX_KEY)
}

fn c_assignment_value_parts(value: Expression) -> (Vec<Expression>, Expression) {
    match value.kind {
        ExprKind::Assign { target, value } => {
            let result = *value;
            let effect = expr(ExprKind::Assign {
                target,
                value: Box::new(result.clone()),
            });
            (vec![effect], result)
        }
        ExprKind::Sequence(mut parts) => {
            let Some(last) = parts.pop() else {
                return (Vec::new(), expr(ExprKind::Sequence(parts)));
            };
            let (nested_prefix, result) = c_assignment_value_parts(last);
            parts.extend(nested_prefix);
            (parts, result)
        }
        other => (Vec::new(), expr(other)),
    }
}

fn is_carray_like_expr(e: &Expression) -> bool {
    if is_carray_object(e) {
        return true;
    }
    match &e.kind {
        ExprKind::Cast { expr, .. } => is_carray_like_expr(expr),
        ExprKind::Ternary { then, else_, .. } => {
            is_carray_like_expr(then)
                || is_carray_like_expr(else_)
                || matches!(else_.kind, ExprKind::Lit(Literal::Null))
                // `ptr_or_null` (wcschr/wcsstr/wmemchr/... "not found") produces the
                // mirror shape `idx < 0 ? null : carray`, so the carray sits in the
                // else branch and null in the then branch. Recognize that too, or
                // `wcschr(...) == 0` won't be normalized to a null-pointer check.
                || (matches!(then.kind, ExprKind::Lit(Literal::Null)) && is_carray_like_expr(else_))
        }
        ExprKind::Call { callee, .. } => {
            let ExprKind::Lambda { body, .. } = &callee.kind else {
                return false;
            };
            match body {
                LambdaBody::Expr(expr) => is_carray_like_expr(expr),
                LambdaBody::Block(_) => false,
            }
        }
        ExprKind::Sequence(parts) => parts.last().map(is_carray_like_expr).unwrap_or(false),
        _ => false,
    }
}

fn expr_contains_carray_object_bounded(e: &Expression, mut budget: usize) -> bool {
    fn visit(e: &Expression, budget: &mut usize) -> bool {
        if *budget == 0 {
            return false;
        }
        *budget -= 1;
        if is_carray_object(e) {
            return true;
        }
        match &e.kind {
            ExprKind::Cast { expr, .. } | ExprKind::RefLoad(expr) => visit(expr, budget),
            ExprKind::Unary { expr, .. } => visit(expr, budget),
            ExprKind::Binary { left, right, .. } => visit(left, budget) || visit(right, budget),
            ExprKind::Ternary { cond, then, else_ } => {
                visit(cond, budget) || visit(then, budget) || visit(else_, budget)
            }
            ExprKind::Sequence(parts) => parts.iter().any(|part| visit(part, budget)),
            ExprKind::Array(parts) => parts.iter().take(8).any(|part| visit(&part.value, budget)),
            ExprKind::Call { callee, args, .. } => {
                visit(callee, budget) || args.iter().any(|arg| visit(&arg.value, budget))
            }
            ExprKind::Member { object, .. } => visit(object, budget),
            ExprKind::Index { object, index, .. } => visit(object, budget) || visit(index, budget),
            ExprKind::Object(props) => props.iter().take(8).any(|prop| match prop {
                ObjectProperty::KeyValue { key, value }
                | ObjectProperty::Computed { key, value } => {
                    visit(key, budget) || visit(value, budget)
                }
                ObjectProperty::Spread(value) => visit(value, budget),
                ObjectProperty::Shorthand(_)
                | ObjectProperty::Method { .. }
                | ObjectProperty::Accessor { .. } => false,
            }),
            _ => false,
        }
    }
    visit(e, &mut budget)
}

fn pointer_ident_name(e: &Expression) -> Option<&str> {
    match &e.kind {
        ExprKind::Ident(name) => Some(name.as_str()),
        ExprKind::RefLoad(inner) => match &inner.kind {
            ExprKind::Ident(name) => Some(name.as_str()),
            _ => None,
        },
        ExprKind::Cast { expr, .. } => pointer_ident_name(expr),
        _ => None,
    }
}

fn c_call_arg_should_preserve_lvalue(callee: &Expression, arg_index: usize) -> bool {
    if arg_index != 0 {
        return false;
    }
    let ExprKind::Ident(name) = &callee.kind else {
        return false;
    };
    let leaf = name.rsplit('.').next().unwrap_or(name.as_str());
    matches!(
        leaf,
        "strcpy"
            | "strncpy"
            | "strlcpy"
            | "strcat"
            | "strncat"
            | "strlcat"
            | "stpcpy"
            | "memcpy"
            | "memmove"
            | "memset"
            | "bzero"
            | "fread"
            | "fgets"
            | "gets"
            | "read"
    )
}

fn c_addressed_ident_name(e: &Expression) -> Option<&str> {
    match &e.kind {
        ExprKind::Ident(name) => Some(name.as_str()),
        ExprKind::Unary {
            op: UnaryOp::AddrOf,
            expr,
        } => match &expr.kind {
            ExprKind::Ident(name) => Some(name.as_str()),
            _ => None,
        },
        ExprKind::RefLoad(inner) => c_addressed_ident_name(inner),
        ExprKind::Cast { expr, .. } => c_addressed_ident_name(expr),
        _ => None,
    }
}

fn c_struct_literal_int_fields(value: &Expression) -> Option<HashMap<String, i64>> {
    let ExprKind::Object(props) = &value.kind else {
        return None;
    };
    let mut out = HashMap::new();
    for prop in props {
        let ObjectProperty::KeyValue { key, value } = prop else {
            continue;
        };
        let ExprKind::Lit(Literal::Str(name)) = &key.kind else {
            continue;
        };
        if name == C_STRUCT_TYPE_KEY
            || name == C_STRUCT_BACKING_POINTER_KEY
            || name == C_FIRST_MEMBER_CONTAINER_KEY
        {
            continue;
        }
        let ExprKind::Lit(Literal::Int(n)) = &value.kind else {
            return None;
        };
        out.insert(name.clone(), *n);
    }
    Some(out)
}

fn c_tm_field(fields: &HashMap<String, i64>, name: &str) -> i64 {
    fields.get(name).copied().unwrap_or(0)
}

fn c_tm_year(fields: &HashMap<String, i64>) -> i64 {
    c_tm_field(fields, "tm_year") + 1900
}

fn c_tm_is_leap(year: i64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn c_tm_yday_from_date(year: i64, mon_zero: i64, mday: i64) -> i64 {
    let month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut yday = 0;
    for mon in 0..mon_zero.clamp(0, 11) as usize {
        yday += month_days[mon];
        if mon == 1 && c_tm_is_leap(year) {
            yday += 1;
        }
    }
    yday + (mday - 1).max(0)
}

fn c_tm_yday(fields: &HashMap<String, i64>) -> i64 {
    if let Some(yday) = fields.get("tm_yday").copied()
        && yday != 0
    {
        return yday;
    }
    c_tm_yday_from_date(
        c_tm_year(fields),
        c_tm_field(fields, "tm_mon"),
        c_tm_field(fields, "tm_mday"),
    )
}

fn c_strftime_pad(value: i64, width: usize, pad: char) -> String {
    let text = value.to_string();
    if text.len() >= width {
        text
    } else {
        format!("{}{}", pad.to_string().repeat(width - text.len()), text)
    }
}

fn c_strftime_code(code: &str, fields: &HashMap<String, i64>) -> Option<String> {
    let year = c_tm_year(fields);
    let mon = c_tm_field(fields, "tm_mon");
    let mday = c_tm_field(fields, "tm_mday");
    let hour = c_tm_field(fields, "tm_hour");
    let min = c_tm_field(fields, "tm_min");
    let sec = c_tm_field(fields, "tm_sec");
    let wday = c_tm_field(fields, "tm_wday");
    let yday = c_tm_yday(fields);
    let month_full = [
        "January", "February", "March", "April", "May", "June", "July", "August",
        "September", "October", "November", "December",
    ];
    let month_abbr = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov",
        "Dec",
    ];
    let weekday_full = [
        "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
    ];
    let weekday_abbr = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let mon_idx = mon.clamp(0, 11) as usize;
    let wday_idx = wday.clamp(0, 6) as usize;
    let hour12 = if hour % 12 == 0 { 12 } else { hour % 12 };
    let monday_zero_wday = (wday + 6) % 7;
    let sunday_week = (yday - wday + 7) / 7;
    let monday_week = (yday - monday_zero_wday + 7) / 7;
    Some(match code {
        "%Y" => year.to_string(),
        "%y" => c_strftime_pad(year % 100, 2, '0'),
        "%m" => c_strftime_pad(mon + 1, 2, '0'),
        "%d" => c_strftime_pad(mday, 2, '0'),
        "%H" => c_strftime_pad(hour, 2, '0'),
        "%M" => c_strftime_pad(min, 2, '0'),
        "%S" => c_strftime_pad(sec, 2, '0'),
        "%A" => weekday_full[wday_idx].to_string(),
        "%a" => weekday_abbr[wday_idx].to_string(),
        "%B" => month_full[mon_idx].to_string(),
        "%b" | "%h" => month_abbr[mon_idx].to_string(),
        "%p" => {
            if hour >= 12 {
                "PM".to_string()
            } else {
                "AM".to_string()
            }
        }
        "%I" => c_strftime_pad(hour12, 2, '0'),
        "%j" => c_strftime_pad(yday + 1, 3, '0'),
        "%w" => wday.to_string(),
        "%u" => {
            if wday == 0 {
                "7".to_string()
            } else {
                wday.to_string()
            }
        }
        "%C" => c_strftime_pad(year / 100, 2, '0'),
        "%F" => c_strftime_const_output("%Y-%m-%d", fields)?,
        "%D" => c_strftime_const_output("%m/%d/%y", fields)?,
        "%R" => c_strftime_const_output("%H:%M", fields)?,
        "%T" => c_strftime_const_output("%H:%M:%S", fields)?,
        "%e" => c_strftime_pad(mday, 2, ' '),
        "%l" => c_strftime_pad(hour12, 2, ' '),
        "%k" => c_strftime_pad(hour, 2, ' '),
        "%%" => "%".to_string(),
        "%U" => c_strftime_pad(sunday_week, 2, '0'),
        "%W" | "%V" => c_strftime_pad(monday_week, 2, '0'),
        "%G" => year.to_string(),
        "%g" => c_strftime_pad(year % 100, 2, '0'),
        "%n" => "\n".to_string(),
        "%t" => "\t".to_string(),
        _ => return None,
    })
}

fn c_strftime_const_output(format: &str, fields: &HashMap<String, i64>) -> Option<String> {
    let mut out = String::new();
    let mut chars = format.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            out.push(ch);
            continue;
        }
        let next = chars.next()?;
        let code = format!("%{next}");
        out.push_str(&c_strftime_code(&code, fields)?);
    }
    Some(out)
}

fn carray_deref_target_name(e: &Expression) -> Option<String> {
    if let ExprKind::Ternary { then, .. } = &e.kind {
        return carray_deref_target_name(then);
    }
    let ExprKind::Index { object, index, .. } = &e.kind else {
        return None;
    };
    let ExprKind::Member {
        object: base_object,
        field: base_field,
        ..
    } = &object.kind
    else {
        return None;
    };
    let ExprKind::Member {
        object: idx_object,
        field: idx_field,
        ..
    } = &index.kind
    else {
        return None;
    };
    if base_field != CARRAY_BASE_KEY || idx_field != CARRAY_IDX_KEY {
        return None;
    }
    let base_name = carray_deref_target_owner_name(base_object)?;
    let idx_name = carray_deref_target_owner_name(idx_object)?;
    (base_name == idx_name).then(|| base_name.clone())
}

fn carray_deref_target_owner_name(e: &Expression) -> Option<&String> {
    match &e.kind {
        ExprKind::Ident(name) => Some(name),
        ExprKind::RefLoad(inner) => match &inner.kind {
            ExprKind::Ident(name) => Some(name),
            _ => None,
        },
        _ => None,
    }
}

fn dynamic_carray_deref_read(ptr: Expression) -> Expression {
    let scalar_read = Expression::new(ExprKind::Unary {
        op: UnaryOp::Deref,
        expr: Box::new(ptr.clone()),
    });
    Expression::new(ExprKind::Ternary {
        cond: Box::new(pointers::is_carray_ptr_kind(ptr.clone())),
        then: Box::new(pointers::carray_deref_read(ptr)),
        else_: Box::new(scalar_read),
    })
}

fn dynamic_carray_deref_write(ptr: Expression, value: Expression) -> Expression {
    let scalar_write = Expression::new(ExprKind::Assign {
        target: Box::new(Expression::new(ExprKind::Unary {
            op: UnaryOp::Deref,
            expr: Box::new(ptr.clone()),
        })),
        value: Box::new(value.clone()),
    });
    Expression::new(ExprKind::Ternary {
        cond: Box::new(pointers::is_carray_ptr_kind(ptr.clone())),
        then: Box::new(call_expr(
            ident("__c_array_set"),
            vec![
                member(ptr.clone(), CARRAY_BASE_KEY),
                member(ptr, CARRAY_IDX_KEY),
                value,
            ],
        )),
        else_: Box::new(scalar_write),
    })
}

fn va_list_sprintf_call(fmt: Expression, ap: Expression) -> Expression {
    expr(ExprKind::Call {
        callee: Box::new(ident("__c_vsprintf")),
        args: vec![Argument::positional(fmt), Argument::positional(member(ap, "__values"))],
        optional: false,
    })
}

fn c_cell_unwrap_expr(value: Expression) -> Expression {
    expr(ExprKind::Ternary {
        cond: Box::new(expr(ExprKind::Binary {
            op: BinOp::Eq,
            left: Box::new(member(value.clone(), "__ref_kind")),
            right: Box::new(str_lit("cell")),
        })),
        then: Box::new(member(value.clone(), "__value")),
        else_: Box::new(value),
    })
}

fn vfprintf_write_expr(file: Expression, text: Expression) -> Expression {
    let stream = c_cell_unwrap_expr(file);
    // stderr writes go through `__c_fputs_h`'s real-stderr arm — never
    // suppressed (the old shape discarded them, plus a literal-text hack).
    let is_stderr = expr(ExprKind::Binary {
        op: BinOp::Or,
        left: Box::new(expr(ExprKind::Binary {
            op: BinOp::Eq,
            left: Box::new(stream.clone()),
            right: Box::new(int_lit(2)),
        })),
        right: Box::new(expr(ExprKind::Binary {
            op: BinOp::Eq,
            left: Box::new(index_expr(stream.clone(), int_lit(8))),
            right: Box::new(str_lit("stderr")),
        })),
    });
    let has_file_handle = expr(ExprKind::Binary {
        op: BinOp::NotEq,
        left: Box::new(expr(ExprKind::TypeOf(Box::new(index_expr(
            ident("__c_file_content"),
            stream.clone(),
        ))))),
        right: Box::new(str_lit("undefined")),
    });
    expr(ExprKind::Ternary {
        cond: Box::new(is_stderr),
        then: Box::new(call_expr(
            ident("__c_fputs_h"),
            vec![text.clone(), int_lit(2)],
        )),
        else_: Box::new(expr(ExprKind::Ternary {
            cond: Box::new(has_file_handle),
            then: Box::new(call_expr(ident("__c_fputs_h"), vec![text.clone(), stream])),
            else_: Box::new(call_expr(ident("__c_stdout_append"), vec![text])),
        })),
    })
}

fn vsscanf_ints_expr(source: Expression, ap: Expression) -> Expression {
    let source_name = "__c_vsscanf_src".to_string();
    let tokens_name = "__c_vsscanf_tokens".to_string();
    let count_name = "__c_vsscanf_count".to_string();
    let n0_name = "__c_vsscanf_n0".to_string();
    let n1_name = "__c_vsscanf_n1".to_string();

    let source_expr = ident(&source_name);
    let tokens_expr = ident(&tokens_name);
    let count_expr = ident(&count_name);
    let n0_expr = ident(&n0_name);
    let n1_expr = ident(&n1_name);
    let values = member(ap, "__values");
    let target0 = index_expr(values.clone(), int_lit(0));
    let target1 = index_expr(values.clone(), int_lit(1));
    let has_second_target = expr(ExprKind::Binary {
        op: BinOp::Gt,
        left: Box::new(member(values, "length")),
        right: Box::new(int_lit(1)),
    });
    let n0_valid = expr(ExprKind::Binary {
        op: BinOp::Eq,
        left: Box::new(n0_expr.clone()),
        right: Box::new(n0_expr.clone()),
    });
    let n1_valid = expr(ExprKind::Binary {
        op: BinOp::And,
        left: Box::new(has_second_target),
        right: Box::new(expr(ExprKind::Binary {
            op: BinOp::Eq,
            left: Box::new(n1_expr.clone()),
            right: Box::new(n1_expr.clone()),
        })),
    });

    expr(ExprKind::Call {
        callee: Box::new(expr(ExprKind::Lambda {
            params: vec![Param {
                name: source_name.clone(),
                type_hint: None,
                default: None,
                pass_by: PassBy::Value,
                is_rest: false,
                is_kwargs: false,
                is_optional: false,
                is_nullable: false,
            }],
            body: LambdaBody::Expr(Box::new(expr(ExprKind::Sequence(vec![
                assign_expr(
                    tokens_expr.clone(),
                    call_expr(
                        member(
                            call_expr(member(source_expr.clone(), "trim"), vec![]),
                            "split",
                        ),
                        vec![str_lit(" ")],
                    ),
                ),
                assign_expr(count_expr.clone(), int_lit(0)),
                assign_expr(
                    n0_expr.clone(),
                    call_expr(
                        ident("Number"),
                        vec![index_expr(tokens_expr.clone(), int_lit(0))],
                    ),
                ),
                expr(ExprKind::Ternary {
                    cond: Box::new(n0_valid),
                    then: Box::new(expr(ExprKind::Sequence(vec![
                        dynamic_carray_deref_write(target0, n0_expr.clone()),
                        assign_expr(count_expr.clone(), int_lit(1)),
                    ]))),
                    else_: Box::new(int_lit(0)),
                }),
                assign_expr(
                    n1_expr.clone(),
                    call_expr(ident("Number"), vec![index_expr(tokens_expr, int_lit(1))]),
                ),
                expr(ExprKind::Ternary {
                    cond: Box::new(n1_valid),
                    then: Box::new(expr(ExprKind::Sequence(vec![
                        dynamic_carray_deref_write(target1, n1_expr),
                        assign_expr(
                            count_expr.clone(),
                            expr(ExprKind::Binary {
                                op: BinOp::Add,
                                left: Box::new(count_expr.clone()),
                                right: Box::new(int_lit(1)),
                            }),
                        ),
                    ]))),
                    else_: Box::new(int_lit(0)),
                }),
                expr(ExprKind::Ternary {
                    cond: Box::new(expr(ExprKind::Binary {
                        op: BinOp::Eq,
                        left: Box::new(member(source_expr, "length")),
                        right: Box::new(int_lit(0)),
                    })),
                    then: Box::new(int_lit(-1)),
                    else_: Box::new(count_expr),
                }),
            ])))),
            is_async: false,
            captures: vec![],
        })),
        args: vec![Argument::positional(source)],
        optional: false,
    })
}

/// Build a new carray pointer retreated by `n`: `{__base, __idx: __idx - n}`.
fn carray_retreat(ptr: Expression, n: Expression) -> Expression {
    let new_idx = Expression::new(ExprKind::Binary {
        op: BinOp::Sub,
        left: Box::new(Expression::new(ExprKind::Member {
            object: Box::new(ptr.clone()),
            field: CARRAY_IDX_KEY.to_string(),
            null_safe: false,
        })),
        right: Box::new(n),
    });
    Expression::new(ExprKind::Object(vec![
        ObjectProperty::KeyValue {
            key: Expression::new(ExprKind::Lit(Literal::Str("__ref_kind".to_string()))),
            value: Expression::new(ExprKind::Lit(Literal::Str(CARRAY_KIND.to_string()))),
        },
        ObjectProperty::KeyValue {
            key: Expression::new(ExprKind::Lit(Literal::Str(CARRAY_BASE_KEY.to_string()))),
            value: Expression::new(ExprKind::Member {
                object: Box::new(ptr),
                field: CARRAY_BASE_KEY.to_string(),
                null_safe: false,
            }),
        },
        ObjectProperty::KeyValue {
            key: Expression::new(ExprKind::Lit(Literal::Str(CARRAY_IDX_KEY.to_string()))),
            value: new_idx,
        },
    ]))
}

fn is_null_pointer_init(init: &Option<Expression>) -> bool {
    matches!(
        init.as_ref().map(|e| &e.kind),
        Some(ExprKind::Lit(Literal::Int(0)) | ExprKind::Lit(Literal::Null))
    )
}

fn same_ident_expr(left: &Expression, right: &Expression) -> bool {
    matches!(
        (&left.kind, &right.kind),
        (ExprKind::Ident(l), ExprKind::Ident(r)) if l == r
    )
}

fn string_search_result_offset(left: &Expression, right: &Expression) -> Option<Expression> {
    fn extract_offset(expr_in: &Expression, right: &Expression) -> Option<Expression> {
        match &expr_in.kind {
            ExprKind::Ternary { then, else_, .. } => {
                extract_offset(else_, right).or_else(|| extract_offset(then, right))
            }
            ExprKind::Call { callee, args, .. } => {
                let ExprKind::Member { object, field, .. } = &callee.kind else {
                    return None;
                };
                if (field != "slice" && field != "substring")
                    || args.len() != 1
                    || !same_ident_expr(object, right)
                {
                    return None;
                }
                Some(args[0].value.clone())
            }
            _ => None,
        }
    }

    extract_offset(left, right)
}

fn char_suffix_base_offset(value: &Expression) -> Option<(String, Expression)> {
    match &value.kind {
        ExprKind::Ident(name) => Some((name.clone(), int_lit(0))),
        ExprKind::Binary {
            op: BinOp::Add,
            left,
            right,
        } => {
            let ExprKind::Ident(base) = &left.kind else {
                return None;
            };
            Some((base.clone(), (**right).clone()))
        }
        ExprKind::Call { callee, args, .. } => {
            let ExprKind::Member { object, field, .. } = &callee.kind else {
                return None;
            };
            if (field != "substring" && field != "slice") || args.len() != 1 {
                return None;
            }
            let ExprKind::Ident(base) = &object.kind else {
                return None;
            };
            Some((base.clone(), args[0].value.clone()))
        }
        _ => None,
    }
}

#[allow(dead_code)]
fn is_putchar_zero_call(e: &Expression) -> bool {
    let ExprKind::Call { callee, args, .. } = &e.kind else {
        return false;
    };
    if !matches!(&callee.kind, ExprKind::Ident(name) if name == "putchar") || args.len() != 1 {
        return false;
    }
    matches!(args[0].value.kind, ExprKind::Lit(Literal::Int(0)))
}

fn strip_putchar_side_effect_value(value: Expression) -> Expression {
    match value.kind {
        ExprKind::Call {
            callee,
            args,
            optional,
        } => {
            if let ExprKind::Ident(name) = &callee.kind {
                if name == "__c_fputc_h" && !args.is_empty() {
                    return strip_putchar_side_effect_value(args[0].value.clone());
                }
                if name == "__c_fputs_h" {
                    return int_lit(0);
                }
            }
            let rewritten_args = args
                .into_iter()
                .map(|mut a| {
                    a.value = strip_putchar_side_effect_value(a.value);
                    a
                })
                .collect();
            expr(ExprKind::Call {
                callee,
                args: rewritten_args,
                optional,
            })
        }
        ExprKind::Binary { op, left, right } => expr(ExprKind::Binary {
            op,
            left: Box::new(strip_putchar_side_effect_value(*left)),
            right: Box::new(strip_putchar_side_effect_value(*right)),
        }),
        ExprKind::Unary { op, expr: inner } => expr(ExprKind::Unary {
            op,
            expr: Box::new(strip_putchar_side_effect_value(*inner)),
        }),
        ExprKind::Cast {
            expr: inner,
            type_name,
        } => expr(ExprKind::Cast {
            expr: Box::new(strip_putchar_side_effect_value(*inner)),
            type_name,
        }),
        ExprKind::Ternary { cond, then, else_ } => expr(ExprKind::Ternary {
            cond: Box::new(strip_putchar_side_effect_value(*cond)),
            then: Box::new(strip_putchar_side_effect_value(*then)),
            else_: Box::new(strip_putchar_side_effect_value(*else_)),
        }),
        other => expr(other),
    }
}

fn normalize_snprintf_literal_args(mut args: Vec<Argument>) -> Vec<Argument> {
    let Some(fmt) = args.first() else {
        return args;
    };
    let ExprKind::Lit(Literal::Str(format_text)) = &fmt.value.kind else {
        return args;
    };
    let specs = printf_value_specs(format_text);
    for (arg_index, spec) in specs.into_iter().enumerate() {
        let Some(arg) = args.get_mut(arg_index + 1) else {
            break;
        };
        match spec {
            's' if is_null_pointer_expr(&arg.value) => {
                arg.value = str_lit("(null)");
            }
            'p' => {
                arg.value = int_lit(0);
            }
            _ => {}
        }
    }
    args
}

fn printf_value_specs(format_text: &str) -> Vec<char> {
    let chars: Vec<char> = format_text.chars().collect();
    let mut specs = Vec::new();
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] != '%' {
            i += 1;
            continue;
        }
        i += 1;
        if i < chars.len() && chars[i] == '%' {
            i += 1;
            continue;
        }
        while i < chars.len() && matches!(chars[i], '-' | '+' | ' ' | '#' | '0') {
            i += 1;
        }
        while i < chars.len() && chars[i].is_ascii_digit() {
            i += 1;
        }
        if i < chars.len() && chars[i] == '.' {
            i += 1;
            while i < chars.len() && chars[i].is_ascii_digit() {
                i += 1;
            }
        }
        while i < chars.len() && matches!(chars[i], 'h' | 'l' | 'L' | 'z' | 'j' | 't') {
            i += 1;
        }
        if i < chars.len() {
            specs.push(chars[i]);
            i += 1;
        }
    }
    specs
}

fn is_null_pointer_expr(value: &Expression) -> bool {
    match &value.kind {
        ExprKind::Lit(Literal::Int(0) | Literal::Null) => true,
        ExprKind::Lit(Literal::Float(v)) if *v == 0.0 => true,
        ExprKind::Cast { expr, .. } => is_null_pointer_expr(expr),
        _ => false,
    }
}

fn is_zero_int_expr(e: &Expression) -> bool {
    matches!(e.kind, ExprKind::Lit(Literal::Int(0)))
}

fn is_c_false_expr(e: &Expression) -> bool {
    matches!(
        e.kind,
        ExprKind::Lit(Literal::Int(0) | Literal::Bool(false) | Literal::Null)
    )
}

fn rewrite_current_loop_continue_to_break(body: Vec<Statement>) -> Vec<Statement> {
    body.into_iter()
        .map(rewrite_current_loop_continue_to_break_stmt)
        .collect()
}

fn rewrite_current_loop_continue_to_break_stmt(mut st: Statement) -> Statement {
    st.kind = match st.kind {
        StmtKind::Continue(ContinueTarget::Implicit) => StmtKind::Break(BreakTarget::Implicit),
        StmtKind::Block(body) => StmtKind::Block(rewrite_current_loop_continue_to_break(body)),
        StmtKind::If {
            cond,
            then_body,
            elifs,
            else_body,
        } => StmtKind::If {
            cond,
            then_body: rewrite_current_loop_continue_to_break(then_body),
            elifs: elifs
                .into_iter()
                .map(|(cond, body)| (cond, rewrite_current_loop_continue_to_break(body)))
                .collect(),
            else_body: else_body.map(rewrite_current_loop_continue_to_break),
        },
        StmtKind::Switch {
            expr,
            cases,
            default,
        } => StmtKind::Switch {
            expr,
            cases: cases
                .into_iter()
                .map(|mut case| {
                    case.body = rewrite_current_loop_continue_to_break(case.body);
                    case
                })
                .collect(),
            default: default.map(rewrite_current_loop_continue_to_break),
        },
        StmtKind::Try {
            body,
            catches,
            else_body,
            finally,
        } => StmtKind::Try {
            body: rewrite_current_loop_continue_to_break(body),
            catches: catches
                .into_iter()
                .map(|mut catch| {
                    catch.body = rewrite_current_loop_continue_to_break(catch.body);
                    catch
                })
                .collect(),
            else_body: else_body.map(rewrite_current_loop_continue_to_break),
            finally: finally.map(rewrite_current_loop_continue_to_break),
        },
        other => other,
    };
    st
}

/// True for a (possibly nested-brace) all-zero aggregate initializer:
/// `0`, `{0}`, `{{0}}`, `{{{0}}}`, `{}` — the C "zero everything" idiom.
fn is_all_zero_init(e: &Expression) -> bool {
    match &e.kind {
        ExprKind::Lit(Literal::Int(0)) => true,
        ExprKind::Array(elems) => elems.iter().all(|el| is_all_zero_init(&el.value)),
        _ => false,
    }
}

fn c_heap_zeroed_bytes_sized(count: Expression) -> Expression {
    call_expr(ident("__c_u8array_new"), vec![count])
}

fn c_retype_heap_allocation_as_bytes(expr: Expression) -> Expression {
    let Some(count) = memory::heap_allocation_count(&expr).cloned() else {
        return expr;
    };
    c_heap_zeroed_bytes_sized(count)
}

// ── setjmp/longjmp: re-entry transform ──────────────────────────────────────

/// If `e` contains a `__c_setjmp("tok")` marker, return its token.
fn find_setjmp_in_expr(e: &Expression) -> Option<String> {
    match &e.kind {
        ExprKind::Call { callee, args, .. } => {
            if let ExprKind::Ident(n) = &callee.kind {
                if n == "__c_setjmp" {
                    if let Some(ExprKind::Lit(Literal::Str(t))) =
                        args.first().map(|a| &a.value.kind)
                    {
                        return Some(t.clone());
                    }
                }
            }
            find_setjmp_in_expr(callee)
                .or_else(|| args.iter().find_map(|a| find_setjmp_in_expr(&a.value)))
        }
        ExprKind::Binary { left, right, .. } => {
            find_setjmp_in_expr(left).or_else(|| find_setjmp_in_expr(right))
        }
        ExprKind::Ternary { cond, then, else_ } => find_setjmp_in_expr(cond)
            .or_else(|| find_setjmp_in_expr(then))
            .or_else(|| find_setjmp_in_expr(else_)),
        ExprKind::Unary { expr, .. } => find_setjmp_in_expr(expr),
        ExprKind::Assign { target, value } => {
            find_setjmp_in_expr(target).or_else(|| find_setjmp_in_expr(value))
        }
        ExprKind::Member { object, .. } => find_setjmp_in_expr(object),
        ExprKind::Index { object, index, .. } => {
            find_setjmp_in_expr(object).or_else(|| find_setjmp_in_expr(index))
        }
        ExprKind::Sequence(items) => items.iter().find_map(find_setjmp_in_expr),
        _ => None,
    }
}

/// Replace every `__c_setjmp(...)` marker in `e` with a read of `val_var`.
fn replace_setjmp_in_expr(e: &mut Expression, val_var: &str) {
    if let ExprKind::Call { callee, .. } = &e.kind {
        if let ExprKind::Ident(n) = &callee.kind {
            if n == "__c_setjmp" {
                *e = ident(val_var);
                return;
            }
        }
    }
    match &mut e.kind {
        ExprKind::Call { callee, args, .. } => {
            replace_setjmp_in_expr(callee, val_var);
            for a in args {
                replace_setjmp_in_expr(&mut a.value, val_var);
            }
        }
        ExprKind::Binary { left, right, .. } => {
            replace_setjmp_in_expr(left, val_var);
            replace_setjmp_in_expr(right, val_var);
        }
        ExprKind::Ternary { cond, then, else_ } => {
            replace_setjmp_in_expr(cond, val_var);
            replace_setjmp_in_expr(then, val_var);
            replace_setjmp_in_expr(else_, val_var);
        }
        ExprKind::Unary { expr, .. } => replace_setjmp_in_expr(expr, val_var),
        ExprKind::Assign { target, value } => {
            replace_setjmp_in_expr(target, val_var);
            replace_setjmp_in_expr(value, val_var);
        }
        ExprKind::Member { object, .. } => replace_setjmp_in_expr(object, val_var),
        ExprKind::Index { object, index, .. } => {
            replace_setjmp_in_expr(object, val_var);
            replace_setjmp_in_expr(index, val_var);
        }
        ExprKind::Sequence(items) => {
            for it in items {
                replace_setjmp_in_expr(it, val_var);
            }
        }
        _ => {}
    }
}

/// Token of the setjmp marker in a statement (looks in the contexts a setjmp
/// call appears: declaration inits, assignments, if/while conditions, returns).
fn find_setjmp_in_stmt(s: &Statement) -> Option<String> {
    match &s.kind {
        StmtKind::VarDecl { declarations, .. } => declarations
            .iter()
            .find_map(|d| d.init.as_ref().and_then(find_setjmp_in_expr)),
        StmtKind::Assign { targets, value, .. } => {
            find_setjmp_in_expr(value).or_else(|| targets.iter().find_map(find_setjmp_in_expr))
        }
        StmtKind::Expr(e) => find_setjmp_in_expr(e),
        StmtKind::If { cond, .. } => find_setjmp_in_expr(cond),
        StmtKind::While { cond, .. } => find_setjmp_in_expr(cond),
        StmtKind::Return(Some(e)) => find_setjmp_in_expr(e),
        _ => None,
    }
}

fn replace_setjmp_in_stmt(s: &mut Statement, val_var: &str) {
    match &mut s.kind {
        StmtKind::VarDecl { declarations, .. } => {
            for d in declarations {
                if let Some(init) = &mut d.init {
                    replace_setjmp_in_expr(init, val_var);
                }
            }
        }
        StmtKind::Assign { targets, value, .. } => {
            replace_setjmp_in_expr(value, val_var);
            for t in targets {
                replace_setjmp_in_expr(t, val_var);
            }
        }
        StmtKind::Expr(e) => replace_setjmp_in_expr(e, val_var),
        StmtKind::If { cond, .. } => replace_setjmp_in_expr(cond, val_var),
        StmtKind::While { cond, .. } => replace_setjmp_in_expr(cond, val_var),
        StmtKind::Return(Some(e)) => replace_setjmp_in_expr(e, val_var),
        _ => {}
    }
}

/// Wrap the tail of a block (from the first statement containing a setjmp marker)
/// in a re-entry loop + try/catch, so the setjmp "returns twice": 0 initially,
/// then the longjmp value when an exception with the matching buf token unwinds.
fn split_top_level_commas(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    let mut in_string = false;
    let mut in_char = false;
    let mut escaped = false;
    for (idx, ch) in text.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if in_string || in_char {
            if ch == '\\' {
                escaped = true;
            } else if in_string && ch == '"' {
                in_string = false;
            } else if in_char && ch == '\'' {
                in_char = false;
            }
            continue;
        }
        match ch {
            '"' => in_string = true,
            '\'' => in_char = true,
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            ',' if depth == 0 => {
                out.push(text[start..idx].trim().to_string());
                start = idx + ch.len_utf8();
            }
            _ => {}
        }
    }
    let tail = text[start..].trim();
    if !tail.is_empty() {
        out.push(tail.to_string());
    }
    out
}

fn wrap_setjmp_in_block(mut stmts: Vec<Statement>, counter: &mut u32) -> Vec<Statement> {
    let found = stmts
        .iter()
        .enumerate()
        .find_map(|(i, s)| find_setjmp_in_stmt(s).map(|t| (i, t)));
    let Some((i, token)) = found else {
        return stmts;
    };
    let n = *counter;
    *counter += 1;
    let val_var = format!("__sj_val{n}");
    let active_var = format!("__sj_active{n}");
    let err_var = format!("__sj_e{n}");

    let mut body = stmts.split_off(i);
    for s in &mut body {
        replace_setjmp_in_stmt(s, &val_var);
    }
    // Recurse in case a later setjmp (for a different buf) follows in the tail.
    body = wrap_setjmp_in_block(body, counter);

    // catch: if (e != null && e.__c_longjmp === token) { val = e.val; active = 1 } else throw e
    let is_match = expr(ExprKind::Binary {
        op: BinOp::And,
        left: Box::new(expr(ExprKind::Binary {
            op: BinOp::NotEq,
            left: Box::new(ident(&err_var)),
            right: Box::new(expr(ExprKind::Lit(Literal::Null))),
        })),
        right: Box::new(expr(ExprKind::Binary {
            op: BinOp::StrictEq,
            left: Box::new(member(ident(&err_var), "__c_longjmp")),
            right: Box::new(str_lit(&token)),
        })),
    });
    let catch_body = vec![if_stmt(
        is_match,
        vec![
            stmt(StmtKind::Expr(assign_expr(
                ident(&val_var),
                member(ident(&err_var), "__c_longjmp_val"),
            ))),
            stmt(StmtKind::Expr(assign_expr(ident(&active_var), int_lit(1)))),
        ],
        Some(vec![stmt(StmtKind::Throw {
            expr: Some(ident(&err_var)),
            cause: None,
        })]),
    )];
    let try_stmt = stmt(StmtKind::Try {
        body,
        catches: vec![CatchClause {
            types: Vec::new(),
            var_name: Some(err_var.clone()),
            stack_var: None,
            body: catch_body,
            when_clause: None,
        }],
        else_body: None,
        finally: None,
    });
    let loop_body = vec![
        stmt(StmtKind::Expr(assign_expr(ident(&active_var), int_lit(0)))),
        try_stmt,
    ];
    stmts.push(var_decl_stmt(&val_var, int_lit(0)));
    stmts.push(var_decl_stmt(&active_var, int_lit(1)));
    stmts.push(stmt(StmtKind::While {
        cond: expr(ExprKind::Binary {
            op: BinOp::NotEq,
            left: Box::new(ident(&active_var)),
            right: Box::new(int_lit(0)),
        }),
        body: loop_body,
        else_body: None,
    }));
    stmts
}

fn base_ident_name(value: &Expression) -> Option<String> {
    match &value.kind {
        ExprKind::Ident(name) => Some(name.clone()),
        ExprKind::Index { object, .. } => base_ident_name(object),
        ExprKind::Object(props) => props.iter().find_map(|prop| {
            let ObjectProperty::KeyValue { key, value } = prop else {
                return None;
            };
            let ExprKind::Lit(Literal::Str(field)) = &key.kind else {
                return None;
            };
            if field == CARRAY_BASE_KEY {
                base_ident_name(value)
            } else {
                None
            }
        }),
        ExprKind::Call { callee, .. } => {
            let ExprKind::Member { object, field, .. } = &callee.kind else {
                return None;
            };
            if field == "substring" || field == "slice" {
                base_ident_name(object)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn static_function_pointer_object_name(value: &Expression) -> Option<String> {
    match &value.kind {
        ExprKind::Ident(name) => Some(name.clone()),
        ExprKind::RefLoad(inner) => static_function_pointer_object_name(inner),
        _ => None,
    }
}

/// Whether evaluating `e` mutates program state, so it must not be duplicated.
/// Covers the index expressions a char-buffer element write reads twice
/// (`s[w++] = c`, `s[f()] = c`).
fn index_has_side_effects(e: &Expression) -> bool {
    match &e.kind {
        ExprKind::Unary { op, expr } => {
            matches!(
                op,
                UnaryOp::PreInc | UnaryOp::PreDec | UnaryOp::PostInc | UnaryOp::PostDec
            ) || index_has_side_effects(expr)
        }
        ExprKind::Assign { .. } | ExprKind::Call { .. } => true,
        ExprKind::Binary { left, right, .. } => {
            index_has_side_effects(left) || index_has_side_effects(right)
        }
        ExprKind::Ternary { cond, then, else_ } => {
            index_has_side_effects(cond)
                || index_has_side_effects(then)
                || index_has_side_effects(else_)
        }
        ExprKind::Index { object, index, .. } => {
            index_has_side_effects(object) || index_has_side_effects(index)
        }
        ExprKind::Member { object, .. } => index_has_side_effects(object),
        // Postfix/prefix inc-dec desugars to a `Sequence([tmp = v, v = v+1, tmp])`,
        // so a bare `Sequence` in an index position carries the increment's side
        // effect. Without this arm the splice reads the index twice and fires the
        // increment twice (`s[w++] = c` advances `w` by 2).
        ExprKind::Sequence(exprs) => exprs.iter().any(index_has_side_effects),
        _ => false,
    }
}

fn char_buffer_target_offset(value: &Expression) -> Option<(String, Expression)> {
    match &value.kind {
        ExprKind::Ident(name) => Some((name.clone(), expr(ExprKind::Lit(Literal::Int(0))))),
        ExprKind::Object(_) => {
            let base = carray_base_expr(value)?;
            let index = carray_idx_expr(value)?;
            let ExprKind::Ident(name) = base.kind else {
                return None;
            };
            Some((name, index))
        }
        ExprKind::Call { callee, args, .. } => {
            if matches!(&callee.kind, ExprKind::Ident(name) if name == "__libc_char_ptr_add")
                && args.len() >= 2
            {
                if let ExprKind::Ident(base) = &args[0].value.kind {
                    return Some((base.clone(), args[1].value.clone()));
                }
            }
            let ExprKind::Member { object, field, .. } = &callee.kind else {
                return None;
            };
            if (field != "substring" && field != "slice") || args.is_empty() {
                return None;
            }
            let ExprKind::Ident(base) = &object.kind else {
                return None;
            };
            Some((base.clone(), args[0].value.clone()))
        }
        _ => None,
    }
}

fn concat_sequence_to_string(mut pieces: Vec<Expression>) -> Expression {
    if pieces.is_empty() {
        return expr(ExprKind::Lit(Literal::Str(String::new())));
    }
    let mut current = pieces.remove(0);
    for piece in pieces {
        current = concat_expr(current, piece);
    }
    current
}

fn merge_designated_value(slot: &mut Expression, value: Expression) {
    if let ExprKind::Object(existing) = &mut slot.kind {
        if let ExprKind::Object(provided) = value.kind {
            for given in provided {
                let ObjectProperty::KeyValue { key, value } = given else {
                    continue;
                };
                let ExprKind::Lit(Literal::Str(gk)) = &key.kind else {
                    existing.push(ObjectProperty::KeyValue { key, value });
                    continue;
                };
                if let Some(target) = existing.iter_mut().find_map(|prop| {
                    if let ObjectProperty::KeyValue { key, value } = prop {
                        if matches!(&key.kind, ExprKind::Lit(Literal::Str(name)) if name == gk) {
                            return Some(value);
                        }
                    }
                    None
                }) {
                    merge_designated_value(target, value);
                } else {
                    existing.push(ObjectProperty::KeyValue { key, value });
                }
            }
            return;
        }
    }
    *slot = value;
}

enum ParsedInteger {
    I64(i64),
    Text(String),
}

fn literal_string_value(value: &Expression) -> Option<String> {
    match &value.kind {
        ExprKind::Lit(Literal::Str(s)) => Some(s.clone()),
        _ => None,
    }
}

/// A call to a runtime helper that returns a C POINTER (string-or-null) —
/// comparisons against the 0 literal must mean "is NULL" for these.
fn is_ptr_returning_helper_call(e: &Expression) -> bool {
    let ExprKind::Call { callee, .. } = &e.kind else {
        return false;
    };
    matches!(&callee.kind, ExprKind::Ident(name) if name == "__c_getenv_h")
}

fn parsed_expression(parsed: ParsedInteger) -> Expression {
    match parsed {
        ParsedInteger::I64(n) => int_lit(n),
        ParsedInteger::Text(s) => str_lit(&s),
    }
}

fn exact_c_int_expr(value: i64) -> Expression {
    const MAX_SAFE_INTEGER: i64 = 9_007_199_254_740_991;
    if (-MAX_SAFE_INTEGER..=MAX_SAFE_INTEGER).contains(&value) {
        return int_lit(value);
    }
    expr(ExprKind::Object(vec![ObjectProperty::KeyValue {
        key: str_lit("__c_exact_int"),
        value: str_lit(&value.to_string()),
    }]))
}

fn flush_stdout_buffer_expr() -> Expression {
    expr(ExprKind::Sequence(vec![
        call_expr(ident("__c_write_stdout"), vec![ident("__c_stdout_buffer")]),
        assign_expr(ident("__c_stdout_buffer"), str_lit("")),
        int_lit(0),
    ]))
}

fn finalize_c_main_body(
    mut body: Vec<Statement>,
    final_body: Vec<Statement>,
    return_type: Option<&str>,
    tmp_counter: &mut u32,
) -> Vec<Statement> {
    if final_body.is_empty() {
        return body;
    }
    rewrite_c_main_returns(&mut body, &final_body, return_type, tmp_counter);
    body.extend(final_body);
    body
}

fn rewrite_c_main_returns(
    body: &mut [Statement],
    final_body: &[Statement],
    return_type: Option<&str>,
    tmp_counter: &mut u32,
) {
    for statement in body {
        match &mut statement.kind {
            StmtKind::Return(value) => {
                let span = statement.span.clone();
                let mut replacement = Vec::new();
                let return_value = value.take().map(|expr_value| {
                    let tmp = format!("__c_main_return_{}", *tmp_counter);
                    *tmp_counter += 1;
                    replacement.push(Statement {
                        kind: StmtKind::VarDecl {
                            declarations: vec![VarDeclarator {
                                pattern: BindingPattern::Ident(tmp.clone()),
                                type_hint: return_type.map(TypeHint::converting),
                                init: Some(expr_value),
                                array_bounds: None,
                                with_events: false,
                            }],
                            kind: VarDeclKind::Let,
                        },
                        span: span.clone(),
                    });
                    ident(&tmp)
                });
                replacement.extend(final_body.iter().cloned());
                replacement.push(Statement {
                    kind: StmtKind::Return(return_value),
                    span: span.clone(),
                });
                statement.kind = StmtKind::Block(replacement);
            }
            StmtKind::Block(stmts) => {
                rewrite_c_main_returns(stmts, final_body, return_type, tmp_counter);
            }
            StmtKind::If {
                then_body,
                elifs,
                else_body,
                ..
            } => {
                rewrite_c_main_returns(then_body, final_body, return_type, tmp_counter);
                for (_, elif_body) in elifs {
                    rewrite_c_main_returns(elif_body, final_body, return_type, tmp_counter);
                }
                if let Some(else_body) = else_body {
                    rewrite_c_main_returns(else_body, final_body, return_type, tmp_counter);
                }
            }
            StmtKind::For { body, .. }
            | StmtKind::ForIn { body, .. }
            | StmtKind::While { body, .. }
            | StmtKind::DoWhile { body, .. }
            | StmtKind::With { body, .. }
            | StmtKind::Using { body, .. }
            | StmtKind::Lock { body, .. } => {
                rewrite_c_main_returns(body, final_body, return_type, tmp_counter);
            }
            StmtKind::Switch { cases, default, .. } => {
                for case in cases {
                    rewrite_c_main_returns(&mut case.body, final_body, return_type, tmp_counter);
                }
                if let Some(default) = default {
                    rewrite_c_main_returns(default, final_body, return_type, tmp_counter);
                }
            }
            StmtKind::Select { arms, default } => {
                for arm in arms {
                    rewrite_c_main_returns(&mut arm.body, final_body, return_type, tmp_counter);
                }
                if let Some(default) = default {
                    rewrite_c_main_returns(default, final_body, return_type, tmp_counter);
                }
            }
            StmtKind::Try {
                body,
                catches,
                else_body,
                finally,
            } => {
                rewrite_c_main_returns(body, final_body, return_type, tmp_counter);
                for catch in catches {
                    rewrite_c_main_returns(&mut catch.body, final_body, return_type, tmp_counter);
                }
                if let Some(else_body) = else_body {
                    rewrite_c_main_returns(else_body, final_body, return_type, tmp_counter);
                }
                if let Some(finally) = finally {
                    rewrite_c_main_returns(finally, final_body, return_type, tmp_counter);
                }
            }
            StmtKind::Labeled { body, .. } => {
                rewrite_c_main_returns(
                    std::slice::from_mut(body.as_mut()),
                    final_body,
                    return_type,
                    tmp_counter,
                );
            }
            StmtKind::MatchStatement { cases, .. } => {
                for case in cases {
                    rewrite_c_main_returns(&mut case.body, final_body, return_type, tmp_counter);
                }
            }
            StmtKind::FunctionDecl { .. }
            | StmtKind::ClassDecl { .. }
            | StmtKind::StructDecl { .. }
            | StmtKind::ModuleDecl { .. }
            | StmtKind::InterfaceDecl { .. }
            | StmtKind::EnumDecl { .. } => {}
            _ => {}
        }
    }
}

fn normalize_parse_int_radix(radix: Expression, input: Expression) -> Expression {
    if !matches!(radix.kind, ExprKind::Lit(Literal::Int(0))) {
        return radix;
    }
    expr(ExprKind::Ternary {
        cond: Box::new(call_expr(
            member(input.clone(), "startsWith"),
            vec![str_lit("0x")],
        )),
        then: Box::new(int_lit(16)),
        else_: Box::new(expr(ExprKind::Ternary {
            cond: Box::new(call_expr(member(input, "startsWith"), vec![str_lit("0")])),
            then: Box::new(int_lit(8)),
            else_: Box::new(int_lit(10)),
        })),
    })
}

fn parse_c_integer_string(
    raw: &str,
    radix_expr: &Expression,
    signed: bool,
) -> Option<(ParsedInteger, String)> {
    let mut s = raw.trim_start();
    let mut is_negative = false;
    if let Some(rest) = s.strip_prefix('-') {
        is_negative = true;
        s = rest;
    } else if let Some(rest) = s.strip_prefix('+') {
        s = rest;
    }

    let explicit_base = match &radix_expr.kind {
        ExprKind::Lit(Literal::Int(n)) => *n as u32,
        _ => return None,
    };
    let mut base = explicit_base;
    if base == 0 {
        if s.starts_with("0x") || s.starts_with("0X") {
            base = 16;
            s = &s[2..];
        } else if s.starts_with('0') {
            base = 8;
            s = &s[1..];
        } else {
            base = 10;
        }
    } else if base == 16 && (s.starts_with("0x") || s.starts_with("0X")) {
        s = &s[2..];
    }

    let digit_len = s
        .char_indices()
        .take_while(|(_, ch)| ch.to_digit(base).is_some())
        .map(|(idx, ch)| idx + ch.len_utf8())
        .last()
        .unwrap_or(0);
    let digits = &s[..digit_len];
    let suffix = s[digit_len..].to_string();
    if digits.is_empty() {
        return Some((ParsedInteger::I64(0), raw.trim_start().to_string()));
    }

    if signed {
        let magnitude = i128::from_str_radix(digits, base).ok()?;
        let value = if is_negative { -magnitude } else { magnitude };
        if let Ok(value) = i64::try_from(value) {
            Some((ParsedInteger::I64(value), suffix))
        } else {
            Some((ParsedInteger::Text(value.to_string()), suffix))
        }
    } else {
        let magnitude = u128::from_str_radix(digits, base).ok()?;
        if magnitude <= i32::MAX as u128 {
            let value = magnitude as i64;
            Some((
                ParsedInteger::I64(if is_negative { -value } else { value }),
                suffix,
            ))
        } else {
            Some((ParsedInteger::Text(magnitude.to_string()), suffix))
        }
    }
}

fn parse_c_float_string(raw: &str) -> Option<(f64, String)> {
    let trimmed_len = raw.len() - raw.trim_start().len();
    let s = raw.trim_start();
    let lower = s.to_ascii_lowercase();
    for (name, value) in [
        ("infinity", f64::INFINITY),
        ("inf", f64::INFINITY),
        ("nan", f64::NAN),
    ] {
        if lower.starts_with(name) {
            return Some((value, s[name.len()..].to_string()));
        }
        if lower.starts_with(&format!("-{name}")) {
            return Some((-value, s[name.len() + 1..].to_string()));
        }
        if lower.starts_with(&format!("+{name}")) {
            return Some((value, s[name.len() + 1..].to_string()));
        }
    }

    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    if i < chars.len() && matches!(chars[i], '+' | '-') {
        i += 1;
    }
    let sign_end = i;
    if i + 1 < chars.len() && chars[i] == '0' && matches!(chars[i + 1], 'x' | 'X') {
        i += 2;
        let mut before = 0usize;
        while i < chars.len() && chars[i].is_ascii_hexdigit() {
            before += 1;
            i += 1;
        }
        let mut after = 0usize;
        if i < chars.len() && chars[i] == '.' {
            i += 1;
            while i < chars.len() && chars[i].is_ascii_hexdigit() {
                after += 1;
                i += 1;
            }
        }
        if before + after == 0 || i >= chars.len() || !matches!(chars[i], 'p' | 'P') {
            return None;
        }
        i += 1;
        if i < chars.len() && matches!(chars[i], '+' | '-') {
            i += 1;
        }
        let exp_start = i;
        while i < chars.len() && chars[i].is_ascii_digit() {
            i += 1;
        }
        if i == exp_start {
            return None;
        }
        let token: String = chars[..i].iter().collect();
        let suffix: String = chars[i..].iter().collect();
        return parse_c_hex_float(&token).map(|value| (value, suffix));
    }

    i = sign_end;
    let mut saw_digit = false;
    while i < chars.len() && chars[i].is_ascii_digit() {
        saw_digit = true;
        i += 1;
    }
    if i < chars.len() && chars[i] == '.' {
        i += 1;
        while i < chars.len() && chars[i].is_ascii_digit() {
            saw_digit = true;
            i += 1;
        }
    }
    if !saw_digit {
        return None;
    }
    if i < chars.len() && matches!(chars[i], 'e' | 'E') {
        let exp_marker = i;
        i += 1;
        if i < chars.len() && matches!(chars[i], '+' | '-') {
            i += 1;
        }
        let exp_start = i;
        while i < chars.len() && chars[i].is_ascii_digit() {
            i += 1;
        }
        if i == exp_start {
            i = exp_marker;
        }
    }
    let token: String = chars[..i].iter().collect();
    let suffix: String = chars[i..].iter().collect();
    token.parse::<f64>().ok().map(|value| {
        let _ = trimmed_len;
        (value, suffix)
    })
}

fn parse_c_hex_float(token: &str) -> Option<f64> {
    let mut s = token;
    let mut sign = 1.0;
    if let Some(rest) = s.strip_prefix('-') {
        sign = -1.0;
        s = rest;
    } else if let Some(rest) = s.strip_prefix('+') {
        s = rest;
    }
    s = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X"))?;
    let (mantissa, exp_text) = s.split_once('p').or_else(|| s.split_once('P'))?;
    let exp: i32 = exp_text.parse().ok()?;
    let mut value = 0.0;
    let mut frac_scale = 1.0 / 16.0;
    let mut after_dot = false;
    for ch in mantissa.chars() {
        if ch == '.' {
            after_dot = true;
            continue;
        }
        let digit = ch.to_digit(16)? as f64;
        if after_dot {
            value += digit * frac_scale;
            frac_scale /= 16.0;
        } else {
            value = value * 16.0 + digit;
        }
    }
    Some(sign * value * 2f64.powi(exp))
}

fn is_null_expr(value: &Expression) -> bool {
    matches!(
        value.kind,
        ExprKind::Lit(Literal::Null) | ExprKind::Lit(Literal::Int(0))
    )
}

fn next_c_strtok_token(input: &str, delim: &str) -> (Option<String>, Option<String>) {
    if delim.is_empty() {
        return if input.is_empty() {
            (None, None)
        } else {
            (Some(input.to_string()), None)
        };
    }
    let delim_chars: HashSet<char> = delim.chars().collect();
    let chars: Vec<char> = input.chars().collect();
    let mut start = 0usize;
    while start < chars.len() && delim_chars.contains(&chars[start]) {
        start += 1;
    }
    if start >= chars.len() {
        return (None, None);
    }
    let mut end = start;
    while end < chars.len() && !delim_chars.contains(&chars[end]) {
        end += 1;
    }
    let token: String = chars[start..end].iter().collect();
    let remaining = if end < chars.len() {
        Some(chars[end + 1..].iter().collect())
    } else {
        None
    };
    (Some(token), remaining)
}

fn char_pointer_offset_from_init(init: &Option<Expression>) -> Option<(String, Expression)> {
    let init_expr = init.as_ref()?;
    let candidate = if let ExprKind::Sequence(items) = &init_expr.kind {
        items.last()?
    } else if let ExprKind::Ternary { then, .. } = &init_expr.kind {
        then.as_ref()
    } else {
        init_expr
    };
    if let ExprKind::Call { callee, args, .. } = &candidate.kind {
        if matches!(&callee.kind, ExprKind::Ident(name) if name == "__libc_char_ptr_add")
            && args.len() >= 2
        {
            if let ExprKind::Ident(base) = &args[0].value.kind {
                return Some((base.clone(), args[1].value.clone()));
            }
        }
    }
    let ExprKind::Call { callee, args, .. } = &candidate.kind else {
        return None;
    };
    let ExprKind::Member { object, field, .. } = &callee.kind else {
        return None;
    };
    if (field != "substring" && field != "slice") || args.len() != 1 {
        return None;
    }
    let ExprKind::Ident(base) = &object.kind else {
        return None;
    };
    Some((base.clone(), args[0].value.clone()))
}

fn carray_base_expr(value: &Expression) -> Option<Expression> {
    let ExprKind::Object(props) = &value.kind else {
        return None;
    };
    props.iter().find_map(|prop| {
        let ObjectProperty::KeyValue { key, value } = prop else {
            return None;
        };
        let ExprKind::Lit(Literal::Str(field)) = &key.kind else {
            return None;
        };
        if field == CARRAY_BASE_KEY {
            Some(value.clone())
        } else {
            None
        }
    })
}

fn carray_allocation_byte_count(value: &Expression) -> Option<Expression> {
    if !is_carray_object(value) {
        return None;
    }
    let idx = carray_idx_expr(value)?;
    if !is_zero_expr(&idx) {
        return None;
    }
    let base = carray_base_expr(value)?;
    let ExprKind::Call { callee, args, .. } = base.kind else {
        return None;
    };
    if !matches!(callee.kind, ExprKind::Ident(ref name) if name == "Array") {
        return None;
    }
    args.first().map(|arg| arg.value.clone())
}

fn carray_idx_expr(value: &Expression) -> Option<Expression> {
    let ExprKind::Object(props) = &value.kind else {
        return None;
    };
    props.iter().find_map(|prop| {
        let ObjectProperty::KeyValue { key, value } = prop else {
            return None;
        };
        let ExprKind::Lit(Literal::Str(field)) = &key.kind else {
            return None;
        };
        if field == CARRAY_IDX_KEY {
            Some(value.clone())
        } else {
            None
        }
    })
}

fn char_assignment_value_to_string(value: Expression) -> Expression {
    if let ExprKind::Lit(Literal::Int(code)) = &value.kind {
        if *code == 0 {
            // Write a real NUL so the C null-terminator survives in the string.
            // Consumers (`printf %s`, `puts`, `strlen`) truncate at the first NUL.
            return expr(ExprKind::Lit(Literal::Str("\0".to_string())));
        }
        if let Some(ch) = char::from_u32(*code as u32) {
            return expr(ExprKind::Lit(Literal::Str(ch.to_string())));
        }
    }
    if matches!(value.kind, ExprKind::Lit(Literal::Str(_))) {
        value
    } else {
        string_adapter::char_code_to_string(value)
    }
}

fn char_assignment_value_to_code(value: &Expression) -> Expression {
    match &value.kind {
        ExprKind::Lit(Literal::Str(s)) => {
            int_lit(s.chars().next().map(|ch| ch as u32 as i64).unwrap_or(0))
        }
        ExprKind::Lit(Literal::Char(ch)) => int_lit(*ch as u32 as i64),
        _ => value.clone(),
    }
}

fn sscanf_target_expr(value: &Expression) -> Expression {
    match &value.kind {
        ExprKind::Unary {
            op: UnaryOp::AddrOf,
            expr,
        } => *expr.clone(),
        _ => value.clone(),
    }
}

fn pointer_address_target_from_init(init: &Option<Expression>) -> Option<String> {
    let ExprKind::Unary {
        op: UnaryOp::AddrOf,
        expr,
    } = &init.as_ref()?.kind
    else {
        return None;
    };
    let ExprKind::Ident(target) = &expr.kind else {
        return None;
    };
    Some(target.clone())
}

fn exact_unsigned_literal_text(raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    let digits: String = trimmed
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .collect();
    if digits.len() < 10 {
        return None;
    }
    let suffix = trimmed[digits.len()..].to_ascii_lowercase();
    if suffix.chars().all(|ch| matches!(ch, 'u' | 'l')) {
        Some(digits)
    } else {
        None
    }
}

fn pointer_member_target_from_init(init: &Option<Expression>) -> Option<Expression> {
    let ExprKind::Unary {
        op: UnaryOp::AddrOf,
        expr,
    } = &init.as_ref()?.kind
    else {
        return None;
    };
    if matches!(
        expr.kind,
        ExprKind::Member { .. } | ExprKind::Index { .. } | ExprKind::Ternary { .. }
    ) {
        Some((**expr).clone())
    } else {
        None
    }
}

fn propagated_pointer_address_alias(
    init: &Option<Expression>,
    aliases: &HashMap<String, String>,
) -> Option<String> {
    let ExprKind::Ident(name) = &init.as_ref()?.kind else {
        return None;
    };
    aliases.get(name).cloned()
}

fn init_is_carray_pointer_var(init: &Option<Expression>, carray_vars: &HashSet<String>) -> bool {
    fn expr_is_carray_pointer_var(expr: &Expression, carray_vars: &HashSet<String>) -> bool {
        match &expr.kind {
            ExprKind::Ident(name) => carray_vars.contains(name),
            ExprKind::Object(_) => is_carray_like_expr(expr),
            ExprKind::Sequence(parts) => parts
                .last()
                .is_some_and(|last| expr_is_carray_pointer_var(last, carray_vars)),
            ExprKind::Ternary { then, else_, .. } => {
                (is_null_expr(then) || expr_is_carray_pointer_var(then, carray_vars))
                    && (is_null_expr(else_) || expr_is_carray_pointer_var(else_, carray_vars))
            }
            _ => false,
        }
    }

    init.as_ref()
        .map(|expr| expr_is_carray_pointer_var(expr, carray_vars))
        .unwrap_or(false)
}

fn should_wrap_pointer_init_as_carray(
    init: &Option<Expression>,
    array_vars: &HashSet<String>,
) -> bool {
    match init.as_ref().map(|e| &e.kind) {
        Some(ExprKind::Ident(name)) => array_vars.contains(name),
        // The allocation SHAPE is owned by `primitives/memory.rs` — ask it
        // rather than re-deriving it here, so a representation change lands in
        // one place. A bare `malloc`/`calloc`/`realloc` call is still matched
        // by name for the paths that reach here before builtin lowering.
        Some(_) if init.as_ref().is_some_and(memory::is_heap_allocation) => true,
        Some(ExprKind::Call { callee, .. }) => {
            matches!(&callee.kind, ExprKind::Ident(name) if name == "malloc" || name == "calloc" || name == "realloc")
        }
        Some(_)
            if init
                .as_ref()
                .map(|e| is_carray_like_expr(e))
                .unwrap_or(false) =>
        {
            false
        }
        Some(_) => false,
        None => false,
    }
}

fn pointer_address_alias_comparison_side(
    aliases: &HashMap<String, String>,
    alias_expr: &Expression,
    address_expr: &Expression,
) -> Option<bool> {
    let ExprKind::Ident(alias_name) = &alias_expr.kind else {
        return None;
    };
    let expected_target = aliases.get(alias_name)?;
    let actual_target = pointer_address_target_from_expr(address_expr)?;
    Some(expected_target == &actual_target)
}

fn pointer_address_target_from_expr(e: &Expression) -> Option<String> {
    let ExprKind::Unary {
        op: UnaryOp::AddrOf,
        expr,
    } = &e.kind
    else {
        return None;
    };
    match &expr.kind {
        ExprKind::Ident(target) => Some(target.clone()),
        ExprKind::RefLoad(inner) => match &inner.kind {
            ExprKind::Ident(target) => Some(target.clone()),
            _ => None,
        },
        _ => None,
    }
}

fn compare_carray_to_array_start(ptr: Expression, array: Expression, op: BinOp) -> Expression {
    let base_eq = call_expr(
        ident("__c_ref_eq"),
        vec![
            expr(ExprKind::Member {
                object: Box::new(ptr.clone()),
                field: CARRAY_BASE_KEY.to_string(),
                null_safe: false,
            }),
            array,
        ],
    );
    let idx_eq = expr(ExprKind::Binary {
        op: BinOp::Eq,
        left: Box::new(expr(ExprKind::Cast {
            expr: Box::new(member(ptr, CARRAY_IDX_KEY)),
            type_name: "int".to_string(),
        })),
        right: Box::new(expr(ExprKind::Lit(Literal::Int(0)))),
    });
    let eq = expr(ExprKind::Binary {
        op: BinOp::And,
        left: Box::new(base_eq),
        right: Box::new(idx_eq),
    });
    if matches!(op, BinOp::NotEq) {
        expr(ExprKind::Unary {
            op: UnaryOp::Not,
            expr: Box::new(eq),
        })
    } else {
        eq
    }
}

fn carray_ptr_equality(left: Expression, right: Expression) -> Expression {
    let base_eq = call_expr(
        ident("__c_ref_eq"),
        vec![
            expr(ExprKind::Member {
                object: Box::new(left.clone()),
                field: CARRAY_BASE_KEY.to_string(),
                null_safe: false,
            }),
            expr(ExprKind::Member {
                object: Box::new(right.clone()),
                field: CARRAY_BASE_KEY.to_string(),
                null_safe: false,
            }),
        ],
    );
    let idx_eq = expr(ExprKind::Binary {
        op: BinOp::Eq,
        left: Box::new(expr(ExprKind::Cast {
            expr: Box::new(member(left, CARRAY_IDX_KEY)),
            type_name: "int".to_string(),
        })),
        right: Box::new(expr(ExprKind::Cast {
            expr: Box::new(member(right, CARRAY_IDX_KEY)),
            type_name: "int".to_string(),
        })),
    });
    expr(ExprKind::Binary {
        op: BinOp::And,
        left: Box::new(base_eq),
        right: Box::new(idx_eq),
    })
}

fn mixed_c_pointer_equality(left: Expression, right: Expression) -> Expression {
    let record_address = |value: Expression| {
        let is_record_pointer = binary_expr(
            BinOp::And,
            binary_expr(
                BinOp::Eq,
                unary_expr(UnaryOp::Typeof, value.clone()),
                str_lit("object"),
            ),
            binary_expr(
                BinOp::Eq,
                member(value.clone(), REF_KIND_KEY),
                str_lit(C_STRUCT_PTR_KIND),
            ),
        );
        ternary_expr(
            is_record_pointer,
            member(value.clone(), CARRAY_BASE_KEY),
            value,
        )
    };
    // Keep record backing out of value bindings: assigning a C record copies
    // it, whereas pointer equality must inspect the original object's identity.
    let left = record_address(left);
    let right = record_address(right);
    let left_is_object = binary_expr(
        BinOp::Eq,
        expr(ExprKind::Unary {
            op: UnaryOp::Typeof,
            expr: Box::new(left.clone()),
        }),
        str_lit("object"),
    );
    let right_is_object = binary_expr(
        BinOp::Eq,
        expr(ExprKind::Unary {
            op: UnaryOp::Typeof,
            expr: Box::new(right.clone()),
        }),
        str_lit("object"),
    );
    let left_backing = member(left.clone(), C_STRUCT_BACKING_POINTER_KEY);
    let right_backing = member(right.clone(), C_STRUCT_BACKING_POINTER_KEY);
    let left_has_backing = binary_expr(
        BinOp::And,
        left_is_object.clone(),
        binary_expr(
            BinOp::NotEq,
            expr(ExprKind::Unary {
                op: UnaryOp::Typeof,
                expr: Box::new(left_backing.clone()),
            }),
            str_lit("undefined"),
        ),
    );
    let right_has_backing = binary_expr(
        BinOp::And,
        right_is_object.clone(),
        binary_expr(
            BinOp::NotEq,
            expr(ExprKind::Unary {
                op: UnaryOp::Typeof,
                expr: Box::new(right_backing.clone()),
            }),
            str_lit("undefined"),
        ),
    );
    let backing_eq = binary_expr(
        BinOp::StrictEq,
        ternary_expr(left_has_backing.clone(), left_backing, left.clone()),
        ternary_expr(right_has_backing.clone(), right_backing, right.clone()),
    );
    let any_backed_struct = binary_expr(BinOp::Or, left_has_backing, right_has_backing);
    expr(ExprKind::Ternary {
        cond: Box::new(any_backed_struct),
        then: Box::new(backing_eq),
        else_: Box::new(expr(ExprKind::Ternary {
            cond: Box::new(binary_expr(
                BinOp::And,
                pointers::is_carray_ptr_kind(left.clone()),
                pointers::is_carray_ptr_kind(right.clone()),
            )),
            then: Box::new(carray_ptr_equality(left.clone(), right.clone())),
            else_: Box::new(binary_expr(BinOp::StrictEq, left, right)),
        })),
    })
}

/// The literal `__idx` of a carray OBJECT literal, when constant.
fn carray_object_literal_idx(e: &Expression) -> Option<i64> {
    let ExprKind::Object(props) = &e.kind else {
        return None;
    };
    for p in props {
        if let ObjectProperty::KeyValue { key, value } = p {
            if matches!(&key.kind, ExprKind::Lit(Literal::Str(k)) if k == CARRAY_IDX_KEY) {
                if let ExprKind::Lit(Literal::Int(i)) = value.kind {
                    return Some(i);
                }
            }
        }
    }
    None
}

fn carray_ptr_relational(left: Expression, right: Expression, op: BinOp) -> Expression {
    let base_eq = expr(ExprKind::Binary {
        op: BinOp::Eq,
        left: Box::new(expr(ExprKind::Member {
            object: Box::new(left.clone()),
            field: CARRAY_BASE_KEY.to_string(),
            null_safe: false,
        })),
        right: Box::new(expr(ExprKind::Member {
            object: Box::new(right.clone()),
            field: CARRAY_BASE_KEY.to_string(),
            null_safe: false,
        })),
    });
    let idx_cmp = expr(ExprKind::Binary {
        op,
        left: Box::new(expr(ExprKind::Member {
            object: Box::new(left),
            field: CARRAY_IDX_KEY.to_string(),
            null_safe: false,
        })),
        right: Box::new(expr(ExprKind::Member {
            object: Box::new(right),
            field: CARRAY_IDX_KEY.to_string(),
            null_safe: false,
        })),
    });
    expr(ExprKind::Binary {
        op: BinOp::And,
        left: Box::new(base_eq),
        right: Box::new(idx_cmp),
    })
}

fn mixed_c_pointer_relational(left: Expression, right: Expression, op: BinOp) -> Expression {
    let names = ["__c_pointer_order_left", "__c_pointer_order_right"];
    let lhs = ident(names[0]);
    let rhs = ident(names[1]);
    let numeric = |value: Expression| {
        expr(ExprKind::IsType {
            expr: Box::new(value),
            type_name: "number".into(),
        })
    };
    let address = |value: Expression| {
        expr(ExprKind::Cast {
            expr: Box::new(value),
            type_name: "uintptr_t".into(),
        })
    };
    let body = ternary_expr(
        binary_expr(BinOp::And, numeric(lhs.clone()), numeric(rhs.clone())),
        binary_expr(op, address(lhs.clone()), address(rhs.clone())),
        carray_ptr_relational(
            pointers::ensure_carray_ptr(lhs),
            pointers::ensure_carray_ptr(rhs),
            op,
        ),
    );
    // Bind each operand once: pointer expressions may advance their cursors.
    call_expr(
        expr(ExprKind::Lambda {
            params: names
                .into_iter()
                .map(|name| Param {
                    name: name.into(),
                    type_hint: None,
                    default: None,
                    pass_by: PassBy::Value,
                    is_rest: false,
                    is_kwargs: false,
                    is_optional: false,
                    is_nullable: false,
                })
                .collect(),
            body: LambdaBody::Expr(Box::new(body)),
            is_async: false,
            captures: vec![],
        }),
        vec![left, right],
    )
}

fn carray_ptr_relational_to_array_start(
    ptr: Expression,
    array: Expression,
    op: BinOp,
    ptr_is_left: bool,
) -> Expression {
    let base_eq = expr(ExprKind::Binary {
        op: BinOp::Eq,
        left: Box::new(expr(ExprKind::Member {
            object: Box::new(ptr.clone()),
            field: CARRAY_BASE_KEY.to_string(),
            null_safe: false,
        })),
        right: Box::new(array),
    });
    let idx = expr(ExprKind::Member {
        object: Box::new(ptr),
        field: CARRAY_IDX_KEY.to_string(),
        null_safe: false,
    });
    let zero = expr(ExprKind::Lit(Literal::Int(0)));
    let idx_cmp = if ptr_is_left {
        expr(ExprKind::Binary {
            op,
            left: Box::new(idx),
            right: Box::new(zero),
        })
    } else {
        expr(ExprKind::Binary {
            op,
            left: Box::new(zero),
            right: Box::new(idx),
        })
    };
    expr(ExprKind::Binary {
        op: BinOp::And,
        left: Box::new(base_eq),
        right: Box::new(idx_cmp),
    })
}

fn atomic_pointer_target(arg: Expression) -> Expression {
    if let ExprKind::Unary {
        op: UnaryOp::AddrOf,
        expr,
    } = arg.kind
    {
        *expr
    } else {
        arg
    }
}

fn nan_to_default(value: Expression, default_value: Expression) -> Expression {
    expr(ExprKind::Ternary {
        cond: Box::new(expr(ExprKind::Binary {
            op: BinOp::NotEq,
            left: Box::new(value.clone()),
            right: Box::new(value.clone()),
        })),
        then: Box::new(default_value),
        else_: Box::new(value),
    })
}

/// Extract an integer value from an optional enum initializer expression.
/// Handles plain integer literals and negated literals (e.g. `= -2`).
/// Falls back to `default` for unsupported forms.
fn extract_enum_val(init: &Option<Expression>, default: i64) -> i64 {
    let Some(e) = init else { return default };
    match &e.kind {
        ExprKind::Lit(Literal::Int(i)) => *i,
        ExprKind::Unary {
            op: UnaryOp::Neg,
            expr,
        } => {
            if let ExprKind::Lit(Literal::Int(i)) = &expr.kind {
                -i
            } else {
                default
            }
        }
        _ => default,
    }
}

/// Returns true if a statement list ends with a break or return (no fallthrough).
fn ends_with_break(stmts: &[Statement]) -> bool {
    match stmts.last() {
        Some(s) => {
            matches!(
                s.kind,
                StmtKind::Break(_)
                    | StmtKind::Continue(_)
                    | StmtKind::Return(_)
                    | StmtKind::GoTo(_)
            ) || matches!(&s.kind, StmtKind::Block(inner) if ends_with_break(inner))
        }
        None => false,
    }
}

/// Convert an expression AST node back to a simple C source string for macro substitution.
/// Only handles the common cases that appear in macro arguments.
fn expr_to_c_source(expr: &Expression) -> String {
    match &expr.kind {
        ExprKind::Lit(Literal::Int(n)) => n.to_string(),
        ExprKind::Lit(Literal::Float(f)) => format!("{}", f),
        ExprKind::Lit(Literal::Str(s)) => {
            format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
        }
        ExprKind::Lit(Literal::Bool(b)) => {
            if *b {
                "1".to_string()
            } else {
                "0".to_string()
            }
        }
        ExprKind::Ident(name) => name.clone(),
        ExprKind::Binary { op, left, right } => {
            let op_str = match op {
                BinOp::Add => "+",
                BinOp::Sub => "-",
                BinOp::Mul => "*",
                BinOp::Div => "/",
                BinOp::Mod => "%",
                BinOp::And => "&&",
                BinOp::Or => "||",
                BinOp::Eq => "==",
                BinOp::NotEq => "!=",
                BinOp::Lt => "<",
                BinOp::LtEq => "<=",
                BinOp::Gt => ">",
                BinOp::GtEq => ">=",
                BinOp::BitAnd => "&",
                BinOp::BitOr => "|",
                BinOp::BitXor => "^",
                BinOp::Shl => "<<",
                BinOp::Shr => ">>",
                _ => "+",
            };
            format!(
                "({} {} {})",
                expr_to_c_source(left),
                op_str,
                expr_to_c_source(right)
            )
        }
        ExprKind::Unary { op, expr: e } => {
            let op_str = match op {
                UnaryOp::Neg => "-",
                UnaryOp::Not => "!",
                UnaryOp::BitNot => "~",
                _ => "",
            };
            format!("({}{})", op_str, expr_to_c_source(e))
        }
        ExprKind::Call { callee, args, .. } => {
            let callee_s = expr_to_c_source(callee);
            let args_s: Vec<String> = args.iter().map(|a| expr_to_c_source(&a.value)).collect();
            format!("{}({})", callee_s, args_s.join(", "))
        }
        _ => "0".to_string(),
    }
}

fn is_complex_type_text(type_text: &str) -> bool {
    type_text.to_ascii_lowercase().contains("complex")
}

fn c_raw_starts_with_call(raw: &str, names: &[&str]) -> bool {
    let trimmed = raw.trim_start();
    names.iter().any(|name| {
        trimmed
            .strip_prefix(name)
            .map(|rest| rest.trim_start().starts_with('('))
            .unwrap_or(false)
    })
}

/// Replace all whole-word occurrences of `word` in `text` with `replacement`.
fn replace_word(text: &str, word: &str, replacement: &str) -> String {
    let mut result = String::with_capacity(text.len());
    let bytes = text.as_bytes();
    let mut i = 0usize;
    let mut in_string = false;
    let mut in_char = false;
    let mut escaped = false;
    while i < text.len() {
        let ch = text[i..].chars().next().unwrap();
        if in_string || in_char {
            result.push(ch);
            i += ch.len_utf8();
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if in_string && ch == '"' {
                in_string = false;
            } else if in_char && ch == '\'' {
                in_char = false;
            }
            continue;
        }
        if ch == '"' {
            in_string = true;
            result.push(ch);
            i += ch.len_utf8();
            continue;
        }
        if ch == '\'' {
            in_char = true;
            result.push(ch);
            i += ch.len_utf8();
            continue;
        }
        if text[i..].starts_with(word) {
            let before_ok = i == 0 || !bytes[i - 1].is_ascii_alphanumeric() && bytes[i - 1] != b'_';
            let end = i + word.len();
            let after_ok =
                end >= text.len() || !bytes[end].is_ascii_alphanumeric() && bytes[end] != b'_';
            if before_ok && after_ok {
                result.push_str(replacement);
                i = end;
                continue;
            }
        }
        result.push(ch);
        i += ch.len_utf8();
    }
    result
}
